        harness["acyclic.harness.v2.HarnessService/Observe"] = new(false, false, true, "none", new[] { "operation:observe" }, new[] { "ERROR_CODE_UNSPECIFIED", "ERROR_CODE_NOT_FOUND", "ERROR_CODE_CONFLICT", "ERROR_CODE_UNSUPPORTED", "ERROR_CODE_INVALID", "ERROR_CODE_UNAUTHORIZED", "ERROR_CODE_STORAGE", "ERROR_CODE_INDETERMINATE", "ERROR_CODE_INTERACTION_DECLINED", "ERROR_CODE_INTERACTION_CANCELLED", "ERROR_CODE_INTERACTION_EXPIRED", "ERROR_CODE_INTERACTION_DENIED" }, new[] { "protocol.identity.exact", "owner.required", "operation_id.nonempty", "scope.required", "scope.capability.operation_observe", "status.identity.matches" });
        harness["acyclic.harness.v2.HarnessService/Cancel"] = new(false, false, true, "operation", new[] { "operation:cancel" }, new[] { "ERROR_CODE_UNSPECIFIED", "ERROR_CODE_NOT_FOUND", "ERROR_CODE_CONFLICT", "ERROR_CODE_UNSUPPORTED", "ERROR_CODE_INVALID", "ERROR_CODE_UNAUTHORIZED", "ERROR_CODE_STORAGE", "ERROR_CODE_INDETERMINATE", "ERROR_CODE_INTERACTION_DECLINED", "ERROR_CODE_INTERACTION_CANCELLED", "ERROR_CODE_INTERACTION_EXPIRED", "ERROR_CODE_INTERACTION_DENIED" }, new[] { "protocol.identity.exact", "owner.required", "operation_id.nonempty", "idempotency_key.nonempty", "scope.required", "scope.capability.operation_cancel", "status.identity.matches" });
        result["harness"] = harness.AsReadOnly();
        return result;
    }

    public static Transport Select(
        string family,
        Runtime runtime,
        bool streaming,
        bool bearerAuth,
        Availability installed,
        Availability endpoint,
        Transport? overrideTransport = null)
    {
        if (!Options.TryGetValue(runtime, out var byFamily) || !byFamily.TryGetValue(family, out var familyOptions))
            throw new ArgumentException($"unknown transport family or runtime: {family}/{runtime}");
        foreach (var option in familyOptions)
        {
            if (overrideTransport == option.Transport && Compatible(option, streaming, bearerAuth, installed, endpoint))
                return option.Transport;
        }
        if (overrideTransport is not null)
            throw new ArgumentException($"unsupported transport override for {family}/{runtime}");
        foreach (var option in familyOptions)
        {
            if (Compatible(option, streaming, bearerAuth, installed, endpoint)) return option.Transport;
        }
        throw new ArgumentException($"no compatible transport for {family}/{runtime}");
    }

    private static bool Compatible(Option option, bool streaming, bool bearerAuth,
        Availability installed, Availability endpoint) => installed.Supports(option.Transport)
        && endpoint.Supports(option.Transport)
        && (!streaming || option.Streaming)
        && (!bearerAuth || option.BearerAuth);

    public static bool RequiresBearer(string family, Runtime runtime)
    {
        if (!Options.TryGetValue(runtime, out var byFamily) ||
            !byFamily.TryGetValue(family, out var familyOptions) || familyOptions.Count == 0)
            throw new ArgumentException($"unknown transport family or runtime: {family}/{runtime}");
        return familyOptions[0].BearerAuth;
    }

    public static string ValidateBearer(string token)
    {
        if (string.IsNullOrWhiteSpace(token) || token.Contains('\r') || token.Contains('\n'))
            throw new ArgumentException("invalid bearer credential", nameof(token));
        return token;
    }

    private static string FirstNonBlank(string? value, string fallback) =>
        string.IsNullOrWhiteSpace(value) ? fallback : value;
}
